function [hl,hlb] = plot_trajectory_percentiles2(H,width)

% H - nf x np x ns array generated by run
% prob_min - np length array of minimum problem data
% solvers_to_plot - indices (3rd dim of H) to show in plot
colors=get(gca,'colororder');
markers={'s','o','^','v','p','<','x','h','+','d','*'};
LW=2;
FS=16;
MS=8;
transparency = 0.2; 

% for clear plots:
%H((H<2e-32)) = 2e-32;
[ns,nf] = size(H); % Grab the dimensions

% Produce a suitable history array with sorted entries:
first_nan = 0;
for i = 1:ns
    nan_yet = false;
    for j = 2:nf
        if ~nan_yet && isnan(H(i,j))
            first_nan = max(first_nan,j);
            nan_yet = true;
        end
        H(i,j) = min(H(i,j), H(i,j-1));
    end
end

if first_nan == 0
    first_nan = nf;
end

xaxis = 1:first_nan;

l = 1;
% POUNDERS
hl(l) = semilogy(1:first_nan,H(1,1:first_nan),'LineWidth',LW,'LineStyle','-','Color',colors(mod(l-1,ns + 1)+1,:),...
        'MarkerSize',MS,'Marker',markers{mod(l-1,ns + 1)+1},'MarkerIndices',floor(linspace(1,nf,10)),...
        'MarkerFaceColor',colors(mod(l-1,ns + 1)+1,:),'MarkerEdgeColor',colors(mod(l-1,ns + 1)+1,:));
hold on

% Left off here. Need to get quantiles at each nf value over i = 2:ns. 
l = 2; 
low = prctile(H(2:ns,1:first_nan),50-width);
for j = 1:first_nan
    if low(j) == 0
        low(j) = low(j-1);
    end
end
med = prctile(H(2:ns,1:first_nan),50);
for j = 1:first_nan
    if med(j) == 0
        med(j) = med(j-1);
    end
end
upp = prctile(H(2:ns,1:first_nan),50+width);
for j = 1:first_nan
    if upp(j) == 0
        upp(j) = upp(j-1);
    end
end
    
% median
hl(l) = semilogy(1:first_nan,med,'LineWidth',LW,'LineStyle','-','Color',colors(mod(l-1,ns + 1)+1,:),...
    'MarkerSize',MS,'Marker',markers{mod(l-1,ns + 1)+1},'MarkerIndices',floor(linspace(1,nf,10)),...
    'MarkerFaceColor',colors(mod(l-1,ns + 1)+1,:),'MarkerEdgeColor',colors(mod(l-1,ns + 1)+1,:));
    
if width > 0
    % quantile bands
    hlb(l) = fill([xaxis,fliplr(xaxis)],[low,fliplr(upp)],colors(mod(l-1,ns)+1,:));
    set(hlb(l),'FaceAlpha',transparency,'EdgeColor',colors(mod(l-1,ns)+1,:));
end

% lines on the boundaries - no markers
semilogy(xaxis,low,'LineWidth',LW-1,'LineStyle','-','Color',colors(mod(l-1,ns)+1,:));
semilogy(xaxis,upp,'LineWidth',LW-1,'LineStyle','-','Color',colors(mod(l-1,ns)+1,:));

ax = gca;
xlim([1,first_nan]);
%ylim(ax,[yl_min,yl_max])
%set(ax,'YTick',linspace(yl_min,yl_max,10))




end